};

export function inputGroupAddonClasses({
  align = "inline-start",
  class: className,
}: {
  align?: InputGroupAddonAlign;
  class?: string | undefined;
} = {}): string {
  return cn(addonBaseClass, addonAlignClasses[align], className);
}

